// SettingServiceHandler is an implementation of the panel.core.v1.SettingService service.
type SettingServiceHandler interface {
	// 读取面板完整设置；字段与 1Panel 的 SettingInfo 一一对应，
	// 未在消息中声明的字段会被丢弃。
	GetInfo(context.Context, *connect.Request[v1.GetSettingInfoRequest]) (*connect.Response[v1.SettingInfo], error)
	// 读取登录后立即需要的精简设置；不要求密码未过期。
	GetBaseInfo(context.Context, *connect.Request[v1.GetSettingBaseInfoRequest]) (*connect.Response[v1.SettingBaseInfo], error)
	// 读取终端外观设置。
	GetTerminal(context.Context, *connect.Request[v1.GetTerminalRequest]) (*connect.Response[v1.TerminalInfo], error)
	// 更新终端外观设置；未填写的字段保持原值。
	UpdateTerminal(context.Context, *connect.Request[v1.UpdateTerminalRequest]) (*connect.Response[v1.UpdateTerminalResponse], error)
	// 更新单个设置项，key 必须是面板已知的设置键。
	UpdateSetting(context.Context, *connect.Request[v1.UpdateSettingRequest]) (*connect.Response[v1.UpdateSettingResponse], error)
	// 读取本机可用的访问地址，供绑定地址下拉框使用。
	GetInterface(context.Context, *connect.Request[v1.GetInterfaceRequest]) (*connect.Response[v1.InterfaceAddresses], error)
	// 读取仪表盘备忘录。
	GetMemo(context.Context, *connect.Request[v1.GetMemoRequest]) (*connect.Response[v1.Memo], error)
	// 更新仪表盘备忘录。
	UpdateMemo(context.Context, *connect.Request[v1.UpdateMemoRequest]) (*connect.Response[v1.UpdateMemoResponse], error)
	// 读取当前用户的文件下载命名偏好。
	GetFileDownloadPreference(context.Context, *connect.Request[v1.GetFileDownloadPreferenceRequest]) (*connect.Response[v1.FileDownloadPreference], error)
	// 更新当前用户的文件下载命名偏好。
	UpdateFileDownloadPreference(context.Context, *connect.Request[v1.UpdateFileDownloadPreferenceRequest]) (*connect.Response[v1.UpdateFileDownloadPreferenceResponse], error)
	// 修改面板监听端口。
	UpdatePort(context.Context, *connect.Request[v1.UpdatePortRequest]) (*connect.Response[v1.UpdatePortResponse], error)
	// 修改面板绑定地址与 IPv6 开关。
	UpdateBindInfo(context.Context, *connect.Request[v1.UpdateBindInfoRequest]) (*connect.Response[v1.UpdateBindInfoResponse], error)
	// 读取面板 HTTPS 证书信息。
	GetSSLInfo(context.Context, *connect.Request[v1.GetSSLInfoRequest]) (*connect.Response[v1.SSLInfo], error)
	// 更新面板 HTTPS 配置。
	UpdateSSL(context.Context, *connect.Request[v1.UpdateSSLRequest]) (*connect.Response[v1.UpdateSSLResponse], error)
	// 重新加载面板 HTTPS 证书，仅允许本机调用。
	ReloadSSL(context.Context, *connect.Request[v1.ReloadSSLRequest]) (*connect.Response[v1.ReloadSSLResponse], error)
	// 下载面板当前使用的证书文件，内容以 base64 返回。
	DownloadSSL(context.Context, *connect.Request[v1.DownloadSSLRequest]) (*connect.Response[v1.SSLFile], error)
	// 读取升级信息：当前版本、最新版本与更新说明。
	GetUpgradeInfo(context.Context, *connect.Request[v1.GetUpgradeInfoRequest]) (*connect.Response[v1.UpgradeInfo], error)
	// 执行面板升级。
	Upgrade(context.Context, *connect.Request[v1.UpgradeRequest]) (*connect.Response[v1.UpgradeResponse], error)
	// 读取指定版本的更新说明。
	GetUpgradeNotes(context.Context, *connect.Request[v1.GetUpgradeNotesRequest]) (*connect.Response[v1.UpgradeNotes], error)
	// 读取全部版本说明列表。
	ListReleases(context.Context, *connect.Request[v1.ListReleasesRequest]) (*connect.Response[v1.ListReleasesResponse], error)
	// 读取应用商店行为配置。
	GetAppStoreConfig(context.Context, *connect.Request[v1.GetAppStoreConfigRequest]) (*connect.Response[v1.AppStoreConfig], error)
	// 更新应用商店行为配置的单项开关。
	UpdateAppStoreConfig(context.Context, *connect.Request[v1.UpdateAppStoreConfigRequest]) (*connect.Response[v1.UpdateAppStoreConfigResponse], error)
	// 更新菜单相关设置项（隐藏菜单、菜单布局等）。
	UpdateMenu(context.Context, *connect.Request[v1.UpdateMenuRequest]) (*connect.Response[v1.UpdateMenuResponse], error)
	// 重置菜单为默认布局。
	DefaultMenu(context.Context, *connect.Request[v1.DefaultMenuRequest]) (*connect.Response[v1.DefaultMenuResponse], error)
	// 更新服务器代理配置。
	UpdateProxy(context.Context, *connect.Request[v1.UpdateProxyRequest]) (*connect.Response[v1.UpdateProxyResponse], error)
	// 探测面板是否可用；用于前端在长时间请求后确认服务仍在。
	GetSystemAvailable(context.Context, *connect.Request[v1.GetSystemAvailableRequest]) (*connect.Response[v1.GetSystemAvailableResponse], error)
}

